package com.studio1111.giyahnameh.data

/**
 * Species-specific editorial upgrades kept separate from the seed lists so content can be
 * reviewed without rewriting the regional catalogue. Each entry is deliberately sourced and
 * distinguishes historical use from demonstrated clinical benefit.
 */
object PlantMonographOverrides {
    private data class Article(
        val description: String,
        val habitat: String,
        val care: String,
        val traditionalUses: String,
        val evidence: String,
        val cautions: String,
        val interactions: String,
        val partsUsed: String,
        val preparation: String,
        val specialPopulations: String,
        val faq: String,
        val bibliography: String,
        val sourceUrl: String
    )

    private val articles = mapOf(
        "panax-quinquefolius" to Article(
            description = "جینسینگ آمریکایی گیاهی علفی و چندساله از خانواده آرالیان است. برگ‌های آن معمولاً به‌صورت چرخه‌ای در بالای ساقه قرار می‌گیرند و هر برگ از چند برگچه دندانه‌دار تشکیل می‌شود. گل‌های کوچک و کم‌جلوه به خوشه‌ای از میوه‌های قرمز تبدیل می‌شوند. ریشه گوشتی و نسبتاً کندرشد بخش اصلی تجارت این گیاه است. آن را نباید با جینسینگ آسیایی (Panax ginseng) یا جینسینگ سیبری که به جنس دیگری تعلق دارد یکی دانست؛ ترکیب شیمیایی و شواهد مربوط به این نام‌های بازاری الزاماً یکسان نیست.",
            habitat = "خاستگاه طبیعی آن جنگل‌های سایه‌دار و مرطوب شرق آمریکای شمالی است. به‌دلیل برداشت تجاری و تخریب زیستگاه، جمعیت‌های وحشی در بخش‌هایی از گستره خود آسیب‌پذیرند. در کشت، خاک جنگلی غنی از مواد آلی، زهکشی مناسب، رطوبت یکنواخت و سایه فیلترشده شرایط بهتری فراهم می‌کند. برداشت ریشه‌های وحشی می‌تواند به جمعیت طبیعی صدمه بزند؛ محصول کشت‌شده و قابل‌ردیابی انتخاب مسئولانه‌تری است.",
            care = "این گیاه برای باغچه آفتاب‌گیر و گرم مناسب نیست. بستر باید خنک، غنی از برگ‌پوسیده و مرطوب اما نه غرقاب باشد. سایه درختان یا توری سایه‌انداز از سوختن برگ‌ها جلوگیری می‌کند. رشد از بذر کند است و بذرها ممکن است برای جوانه‌زنی به دوره خواب و سرمادهی نیاز داشته باشند؛ بذر خشک یا نگهداری‌شده نامناسب ممکن است دیر سبز شود. خاک را با مالچ برگ حفظ کنید، علف‌های هرز را با دست بردارید و از کندن ریشه پیش از رسیدگی چندساله خودداری کنید. پوسیدگی ریشه در خاک ماندابی و بیماری‌های قارچی از مشکلات مهم کشت هستند.",
            traditionalUses = "ریشه جینسینگ آمریکایی در برخی سنت‌های بومی آمریکای شمالی و سپس در تجارت گیاهان دارویی به‌عنوان مقوی و برای خستگی، تمرکز و سازگاری با فشارهای روزمره استفاده شده است. در طب سنتی شرق آسیا نیز بعدها به‌عنوان گیاهی با طبع و کاربرد متفاوت از جینسینگ آسیایی شناخته شد. این‌ها سابقه مصرف فرهنگی‌اند، نه اثبات اینکه ریشه بتواند بیماری مشخصی را درمان کند. فرآورده‌های ریشه، عصاره‌های استانداردشده و ترکیبات چندگیاهی از نظر مقدار مواد مؤثر یکسان نیستند.",
            evidence = "مطالعات انسانی درباره جینسینگ آمریکایی محدود و وابسته به فرآورده و پیامد مورد بررسی‌اند. بعضی پژوهش‌های کوچک اثر احتمالی بر خستگی یا برخی شاخص‌های مرتبط با سرماخوردگی را بررسی کرده‌اند، اما نتایج برای توصیه درمانی قطعی کافی نیستند و نمی‌توان آن‌ها را به هر مکملی تعمیم داد. شواهد یک گونه جینسینگ نباید به گونه دیگر منتقل شود. این گیاه جایگزین ارزیابی پزشکی برای خستگی پایدار، اختلال تمرکز یا عفونت نیست.",
            cautions = "ممکن است سردرد، بی‌خوابی، ناراحتی گوارشی یا واکنش حساسیتی رخ دهد. کیفیت مکمل‌ها متغیر است و گاهی ترکیب واقعی با برچسب همخوانی ندارد. ریشه خام، پودر، عصاره و فرآورده ترکیبی قابل‌جایگزینی با یکدیگر نیستند. در صورت بروز علائم حساسیت یا عارضه قابل‌توجه، مصرف را متوقف کنید و ارزیابی پزشکی بگیرید.",
            interactions = "جینسینگ ممکن است با داروهای دیابت بر قند خون اثر بگذارد و درباره مصرف هم‌زمان با وارفارین و برخی داروهای دیگر نگرانی یا داده‌های متناقض وجود دارد. اگر داروی ضدانعقاد، داروی کنترل قند، داروی سرکوب ایمنی یا درمان بیماری مزمن مصرف می‌کنید، پیش از استفاده مکملی با پزشک یا داروساز مشورت کنید؛ فهرست تداخل‌ها کامل نیست.",
            partsUsed = "در فرآورده‌های سنتی معمولاً ریشه استفاده می‌شود؛ برگ و میوه را نباید بدون بررسی جداگانه همانند ریشه فرض کرد. سن گیاه، زمان برداشت، شرایط خشک‌کردن و اصالت گونه بر ترکیب نهایی اثر می‌گذارند. نام روی بسته به‌تنهایی تضمین نمی‌کند که محصول واقعاً Panax quinquefolius باشد.",
            preparation = "در سنت‌های گیاهی، ریشه خشک‌شده به‌صورت برش، پودر یا جزء یک فرآورده ترکیبی عرضه شده است. در این پرونده دستور دوز درمانی ارائه نمی‌شود، چون شواهد و غلظت محصولات متفاوت‌اند. از ریشه ناشناس، عصاره خانگی غلیظ یا محصولی با برچسب نامشخص استفاده نکنید و مکمل را برای درمان بیماری جایگزین داروی تجویزشده نکنید.",
            specialPopulations = "ایمنی مکمل جینسینگ آمریکایی در بارداری و شیردهی به‌خوبی مشخص نیست؛ در این دوره‌ها از مصرف دارویی خودسرانه پرهیز کنید. کودکان نباید مکمل بزرگسالان را دریافت کنند. افراد مبتلا به دیابت، اختلال انعقاد، بیماری‌های خودایمنی یا کسانی که داروهای منظم مصرف می‌کنند باید پیش از استفاده با متخصص مشورت کنند.",
            faq = "آیا جینسینگ آمریکایی همان جینسینگ آسیایی است؟ خیر؛ دو گونه متفاوت‌اند. آیا برای خستگی درمان قطعی است؟ خیر؛ شواهد محدود و وابسته به فرآورده است. آیا می‌توان ریشه وحشی را از طبیعت برداشت؟ برداشت ممکن است به جمعیت‌های طبیعی آسیب بزند و قوانین محلی نیز ممکن است محدودیت داشته باشند؛ محصول کشت‌شده و قابل‌ردیابی بهتر است.",
            bibliography = "مرکز ملی سلامت مکمل و تلفیقی آمریکا (NCCIH)، Asian Ginseng برای زمینه ایمنی جنس Panax و محدودیت تعمیم شواهد: https://www.nccih.nih.gov/health/asian-ginseng ؛ برای شناسایی گونه و وضعیت گیاه‌شناسی، Plants of the World Online، Royal Botanic Gardens, Kew: https://powo.science.kew.org/results?q=Panax%20quinquefolius. منبع NCCIH درباره جینسینگ آسیایی، منبع مستقیم اثربخشی جینسینگ آمریکایی نیست و در این مقاله صرفاً برای احتیاط در تعمیم استفاده شده است.",
