            faq = "آیا هی شو وو برای سیاه‌کردن مو ثابت شده است؟ شواهد قابل‌اعتماد برای نتیجه قطعی کافی نیست. آیا نوع فرآوری‌شده کاملاً بی‌خطر است؟ خیر؛ فرآوری خطر را تضمین‌شده حذف نمی‌کند. آیا می‌توان آن را در خانه جوشاند و مصرف کرد؟ با توجه به گزارش‌های آسیب کبدی، این کار توصیه نمی‌شود.",
            bibliography = "LiverTox، Polygonum Multiflorum: https://www.ncbi.nlm.nih.gov/books/NBK548795/ ؛ مرور نظام‌مند گزارش‌های آسیب کبدی در PubMed Central: https://pmc.ncbi.nlm.nih.gov/articles/PMC4306360/ ؛ Kew POWO برای رده‌بندی: https://powo.science.kew.org/results?q=Fallopia%20multiflora. منابع پزشکی نشان می‌دهند خطر آسیب کبدی واقعی است و فرآوری سنتی تضمین ایمنی نیست.",
            sourceUrl = "https://www.ncbi.nlm.nih.gov/books/NBK548795/"
        )
    )

    fun apply(plant: Plant): Plant {
        val article = articles[plant.id] ?: return plant
        return plant.copy(
            description = article.description,
            habitat = article.habitat,
            care = article.care,
            traditionalUses = article.traditionalUses,
            evidence = article.evidence,
            cautions = article.cautions,
            interactions = article.interactions,
            partsUsed = article.partsUsed,
            preparation = article.preparation,
            specialPopulations = article.specialPopulations,
            faq = article.faq,
            bibliography = article.bibliography,
            sourceUrl = article.sourceUrl
        )
    }

    fun coveredSpecies(): Set<String> = articles.keys
}
